const esc = value => String(value).replace(/[&<>\"]/g, ch => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[ch]));
function table(headers, rows, caption) {
  return `<div class="table-wrap" tabindex="0" aria-label="${esc(caption)}"><table><caption>${esc(caption)}</caption><thead><tr>${headers.map(h=>`<th scope="col">${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map(cell=>`<td>${esc(cell)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
}
function inputs(items, id) {
  return `<div class="calculator-grid">${items.map(([key,value,label])=>`<label for="${id}-${key}">${esc(label)}<input id="${id}-${key}" aria-describedby="${id}-note ${id}-error" data-input="${key}" type="number" min="${key==='hours'?40:0}" ${key==='percent'?'max="100"':''} step="${['inquiries','opportunities','customers','hours'].includes(key)?'1':'any'}" value="${value}"></label>`).join('')}</div>`;
}
function calculator(kind, items, labels, note, title) {
  return `<div class="inbound-calculator" data-inbound-calc="${kind}"><h3>${esc(title)}</h3><p>${esc(ui.private)}</p>${inputs(items,kind)}<p class="calculator-error" id="${kind}-error" role="alert" data-error hidden>${esc(ui.invalid)}</p><div class="calculator-results" aria-live="polite" aria-atomic="true">${labels.map((label,i)=>`<div><span>${esc(label)}</span><strong data-output="${i}">—</strong></div>`).join('')}</div><p class="tool-note" id="${kind}-note">${esc(note)}</p></div>`;
}
function render(page) {
  const pack = packs[page.path];
  const prices = publicPrices[page.path];
  if (!pack && !prices && page.path !== '/compare/b2b-seo-vs-ppc/') return '';
  let html = `<section class="inbound-workshop" id="worked-examples"><p class="eyebrow">${esc(work)}</p><h2>${esc(pack?.heading || prices?.heading || comparison.heading)}</h2>`;
  if (pack) html += `<aside class="callout">${esc(disclosure)}</aside><p>${esc(pack.intro)}</p>${table(pack.headers,pack.rows,pack.heading)}<h3>${esc(illustrative)}</h3><p>${esc(pack.plan)}</p><p>${esc(allocation)}</p>`;
  if (prices) html += `<p>${esc(pricingNote)}</p>${table(priceHeaders,prices.rows.map(row=>row.slice(0,3)),prices.heading)}<div class="text-links">${prices.rows.map(row=>`<a href="${esc(row[3])}"><span>${esc(sourceLabel)}</span>: ${esc(row[0])}</a>`).join('')}</div>`;
  if (page.path === '/guides/google-ads-management-cost/') html += calculator('fees',feeFields,feeLabels,feeNote,'Compare fee models');
  if (page.path === '/compare/b2b-seo-vs-ppc/') html += `<aside class="callout">${esc(disclosure)}</aside><p>${esc(comparison.intro)}</p>${table(comparison.headers,comparison.rows,comparison.heading)}<p>${esc(comparison.note)}</p>`;
  if (page.path === '/guides/aeo-agency-pricing/') html += calculator('scope',quoteFields,quoteLabels,quoteNote,'Scope estimator');
  if (['/guides/google-ads-management-cost/','/compare/b2b-seo-vs-ppc/'].includes(page.path)) html += calculator('acquisition',fields,[ui.total,ui.opportunity,ui.cac,ui.ratio],ui.note,ui.calculator);
  return html + '</section>';
}
function renderNav(page) {
  if (!packs[page.path] && !publicPrices[page.path] && page.path !== '/compare/b2b-seo-vs-ppc/') return '';
  return `<nav class="service-navigation" aria-label="Explore services">${nav.map(([href,label])=>`<a href="${href}"${page.path===href?' aria-current="page"':''}>${label}</a>`).join('')}</nav>`;
}
module.exports = { render, renderNav, dictionaries, packs, publicPrices, disclosure };
